1	"use server";
2	
3	import { promises as fs } from "node:fs";
4	import { join } from "node:path";
5	import { revalidatePath } from "next/cache";
6	import { db } from "./db";
7	import { requireAdmin } from "./auth";
8	
9	import { BOARD_UPLOAD_DIR } from "./board-shared";
10	
11	const DEFAULT_COLUMNS = ["Ideas", "Backlog", "In progress", "Review", "Done"];
12	
13	export type BoardSummary = { id: string; name: string; cardCount: number };
14	export type CardSummary = {
15	  id: string;
16	  title: string;
17	  type: string;
18	  priority: string;
19	  labels: string[];
20	  assignee: string | null;
21	  attachmentCount: number;
22	  commentCount: number;
23	  hasDescription: boolean;
24	};
25	export type ColumnData = { id: string; name: string; position: number; cards: CardSummary[] };
26	export type BoardData = { id: string; name: string; columns: ColumnData[] };
27	export type CardDetail = CardSummary & {
28	  description: string;
29	  columnId: string;
30	  attachments: { id: string; filename: string; kind: string; mime: string; sizeBytes: number; url: string }[];
31	  comments: { id: string; authorName: string; body: string; createdAt: string }[];
32	};
33	
34	/** All boards, newest first. Seeds a default "Nxeon" board on first use. */
35	export async function listBoards(): Promise<BoardSummary[]> {
36	  await requireAdmin();
37	  let boards = await db.board.findMany({ orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
38	  if (boards.length === 0) {
39	    await createBoardInternal("Nxeon");
40	    boards = await db.board.findMany({ orderBy: { createdAt: "asc" }, include: { _count: { select: { cards: true } } } });
41	  }
42	  return boards.map((b) => ({ id: b.id, name: b.name, cardCount: b._count.cards }));
43	}
44	
45	async function createBoardInternal(name: string): Promise<string> {
46	  const board = await db.board.create({ data: { name } });
47	  await db.boardColumn.createMany({ data: DEFAULT_COLUMNS.map((n, i) => ({ boardId: board.id, name: n, position: i })) });
48	  return board.id;
49	}
50	
51	export async function createBoard(name: string): Promise<{ id?: string; error?: string }> {
52	  await requireAdmin();
53	  const clean = String(name ?? "").trim().slice(0, 60);
54	  if (!clean) return { error: "Enter a board name." };
55	  const id = await createBoardInternal(clean);
56	  revalidatePath("/admin/board");
57	  return { id };
58	}
59	
60	export async function renameBoard(id: string, name: string): Promise<void> {
61	  await requireAdmin();
62	  const clean = String(name ?? "").trim().slice(0, 60);
63	  if (clean) await db.board.update({ where: { id }, data: { name: clean } });
64	  revalidatePath("/admin/board");
65	}
66	
67	export async function deleteBoard(id: string): Promise<void> {
68	  await requireAdmin();
69	  await db.board.delete({ where: { id } }).catch(() => undefined);
70	  await fs.rm(join(BOARD_UPLOAD_DIR, "board", id), { recursive: true, force: true }).catch(() => undefined);
71	  revalidatePath("/admin/board");
72	}
73	
74	/** Full board with columns + card summaries (non-archived). */
75	export async function getBoard(boardId: string): Promise<BoardData | null> {
76	  await requireAdmin();
77	  const board = await db.board.findUnique({
78	    where: { id: boardId },
79	    include: {
80	      columns: {
81	        orderBy: { position: "asc" },
82	        include: {
83	          cards: {
84	            where: { archivedAt: null },
85	            orderBy: { position: "asc" },
86	            include: { _count: { select: { attachments: true, comments: true } } },
87	          },
88	        },
89	      },
90	    },
91	  });
92	  if (!board) return null;
93	  return {
94	    id: board.id,
95	    name: board.name,
96	    columns: board.columns.map((c) => ({
97	      id: c.id,
98	      name: c.name,
99	      position: c.position,
100	      cards: c.cards.map((card) => ({
101	        id: card.id,
102	        title: card.title,
103	        type: card.type,
104	        priority: card.priority,
105	        labels: card.labels,
106	        assignee: card.assignee,
107	        attachmentCount: card._count.attachments,
108	        commentCount: card._count.comments,
109	        hasDescription: card.description.trim().length > 0,
110	      })),
111	    })),
112	  };
113	}
114	
115	// ---- Columns ---------------------------------------------------------------
116	
117	export async function createColumn(boardId: string, name: string): Promise<void> {
118	  await requireAdmin();
119	  const clean = String(name ?? "").trim().slice(0, 40);
120	  if (!clean) return;
121	  const max = await db.boardColumn.aggregate({ where: { boardId }, _max: { position: true } });
122	  await db.boardColumn.create({ data: { boardId, name: clean, position: (max._max.position ?? -1) + 1 } });
123	  revalidatePath("/admin/board");
124	}
125	
126	export async function renameColumn(id: string, name: string): Promise<void> {
127	  await requireAdmin();
128	  const clean = String(name ?? "").trim().slice(0, 40);
129	  if (clean) await db.boardColumn.update({ where: { id }, data: { name: clean } });
130	  revalidatePath("/admin/board");
131	}
132	
133	export async function deleteColumn(id: string): Promise<{ error?: string }> {
134	  await requireAdmin();
135	  const cards = await db.card.count({ where: { columnId: id, archivedAt: null } });
136	  if (cards > 0) return { error: "Move or archive its cards first." };
137	  await db.boardColumn.delete({ where: { id } }).catch(() => undefined);
138	  revalidatePath("/admin/board");
139	  return {};
140	}
141	
142	// ---- Cards -----------------------------------------------------------------
143	
144	const TYPES = ["IDEA", "FEATURE", "BUG", "CHORE"];
145	const PRIORITIES = ["LOW", "NORMAL", "HIGH", "URGENT"];
146	
147	export async function createCard(columnId: string, title: string, type = "FEATURE"): Promise<{ id?: string; error?: string }> {
148	  await requireAdmin();
149	  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
150	  if (!col) return { error: "Column not found." };
151	  const clean = String(title ?? "").trim().slice(0, 200);
152	  if (!clean) return { error: "Enter a title." };
153	  const max = await db.card.aggregate({ where: { columnId }, _max: { position: true } });
154	  const card = await db.card.create({
155	    data: { boardId: col.boardId, columnId, title: clean, type: (TYPES.includes(type) ? type : "FEATURE") as never, position: (max._max.position ?? -1) + 1 },
156	  });
157	  revalidatePath("/admin/board");
158	  return { id: card.id };
159	}
160	
161	export async function updateCard(
162	  id: string,
163	  patch: { title?: string; description?: string; type?: string; priority?: string; labels?: string[]; assignee?: string | null },
164	): Promise<{ error?: string }> {
165	  await requireAdmin();
166	  const data: Record<string, unknown> = {};
167	  if (patch.title !== undefined) { const t = patch.title.trim().slice(0, 200); if (!t) return { error: "Title can’t be empty." }; data.title = t; }
168	  if (patch.description !== undefined) data.description = patch.description.slice(0, 20_000);
169	  if (patch.type !== undefined && TYPES.includes(patch.type)) data.type = patch.type;
170	  if (patch.priority !== undefined && PRIORITIES.includes(patch.priority)) data.priority = patch.priority;
171	  if (patch.labels !== undefined) data.labels = patch.labels.map((l) => l.trim().slice(0, 24)).filter(Boolean).slice(0, 8);
172	  if (patch.assignee !== undefined) data.assignee = patch.assignee?.trim().slice(0, 40) || null;
173	  await db.card.update({ where: { id }, data });
174	  revalidatePath("/admin/board");
175	  return {};
176	}
177	
178	/** Move a card to a column at a position; renumber siblings. */
179	export async function moveCard(cardId: string, toColumnId: string, toIndex: number): Promise<void> {
180	  await requireAdmin();
181	  const card = await db.card.findUnique({ where: { id: cardId }, select: { columnId: true, boardId: true } });
182	  const col = await db.boardColumn.findUnique({ where: { id: toColumnId }, select: { boardId: true } });
183	  if (!card || !col || col.boardId !== card.boardId) return;
184	  const siblings = await db.card.findMany({ where: { columnId: toColumnId, archivedAt: null, NOT: { id: cardId } }, orderBy: { position: "asc" }, select: { id: true } });
185	  const order = siblings.map((s) => s.id);
186	  const idx = Math.max(0, Math.min(toIndex, order.length));
187	  order.splice(idx, 0, cardId);
188	  await db.$transaction([
189	    db.card.update({ where: { id: cardId }, data: { columnId: toColumnId } }),
190	    ...order.map((id, i) => db.card.update({ where: { id }, data: { position: i } })),
191	  ]);
192	  revalidatePath("/admin/board");
193	}
194	
195	export async function archiveCard(id: string): Promise<void> {
196	  await requireAdmin();
197	  await db.card.update({ where: { id }, data: { archivedAt: new Date() } });
198	  revalidatePath("/admin/board");
199	}
200	
201	/** Hard-delete a card and everything under it: its on-disk attachment files, then
202	 *  the row (attachments + comments cascade). Unlike archiveCard this is permanent. */
203	export async function deleteCard(id: string): Promise<void> {
204	  await requireAdmin();
205	  await fs.rm(join(BOARD_UPLOAD_DIR, "board", id), { recursive: true, force: true }).catch(() => undefined);
206	  await db.card.delete({ where: { id } }).catch(() => undefined);
207	  revalidatePath("/admin/board");
208	}
209	
210	export async function getCard(id: string): Promise<CardDetail | null> {
211	  await requireAdmin();
212	  const c = await db.card.findUnique({ where: { id }, include: { attachments: { orderBy: { createdAt: "asc" } }, comments: { orderBy: { createdAt: "asc" } } } });
213	  if (!c) return null;
214	  return {
215	    id: c.id,
216	    title: c.title,
217	    type: c.type,
218	    priority: c.priority,
219	    labels: c.labels,
220	    assignee: c.assignee,
221	    columnId: c.columnId,
222	    description: c.description,
223	    hasDescription: c.description.trim().length > 0,
224	    attachmentCount: c.attachments.length,
225	    commentCount: c.comments.length,
226	    attachments: c.attachments.map((a) => ({ id: a.id, filename: a.filename, kind: a.kind, mime: a.mime, sizeBytes: a.sizeBytes, url: `/api/board/attachments/${a.id}` })),
227	    comments: c.comments.map((m) => ({ id: m.id, authorName: m.authorName, body: m.body, createdAt: m.createdAt.toISOString() })),
228	  };
229	}
230	
231	export async function addComment(cardId: string, body: string): Promise<{ error?: string }> {
232	  const admin = await requireAdmin();
233	  const clean = String(body ?? "").trim().slice(0, 5000);
234	  if (!clean) return { error: "Write something." };
235	  await db.cardComment.create({ data: { cardId, authorName: admin.email.split("@")[0], body: clean } });
236	  revalidatePath("/admin/board");
237	  return {};
238	}
239	
240	export async function deleteAttachment(id: string): Promise<void> {
241	  await requireAdmin();
242	  const a = await db.cardAttachment.findUnique({ where: { id } });
243	  if (!a) return;
244	  await db.cardAttachment.delete({ where: { id } }).catch(() => undefined);
245	  await fs.rm(join(BOARD_UPLOAD_DIR, "board", a.cardId, a.storedName), { force: true }).catch(() => undefined);
