1	"use client";
2	
3	import { useEffect, useRef, useState, type ClipboardEvent } from "react";
4	import { useRouter } from "next/navigation";
5	import {
6	  createBoard,
7	  createColumn,
8	  createCard,
9	  moveCard,
10	  getCard,
11	  updateCard,
12	  addComment,
13	  archiveCard,
14	  deleteCard,
15	  deleteAttachment,
16	  type BoardSummary,
17	  type BoardData,
18	  type ColumnData,
19	  type CardSummary,
20	  type CardDetail,
21	} from "@/lib/actions-board";
22	
23	const TYPE_TONE: Record<string, string> = {
24	  IDEA: "bg-sky-500/15 text-sky-300",
25	  FEATURE: "bg-brand-500/15 text-brand-200",
26	  BUG: "bg-red-500/15 text-red-300",
27	  CHORE: "bg-slate-500/20 text-slate-300",
28	};
29	const PRIORITY_DOT: Record<string, string> = { LOW: "bg-slate-500", NORMAL: "bg-sky-400", HIGH: "bg-amber-400", URGENT: "bg-red-400" };
30	const TYPES = ["IDEA", "FEATURE", "BUG", "CHORE"];
31	const PRIORITIES = ["LOW", "NORMAL", "HIGH", "URGENT"];
32	
33	export function BoardClient({ boards, board }: { boards: BoardSummary[]; board: BoardData | null }) {
34	  const router = useRouter();
35	  const [openCard, setOpenCard] = useState<string | null>(null);
36	  const [drag, setDrag] = useState<string | null>(null);
37	  // Local column state for optimistic moves.
38	  const [cols, setCols] = useState<ColumnData[]>(board?.columns ?? []);
39	  useEffect(() => setCols(board?.columns ?? []), [board?.id, board?.columns]);
40	
41	  async function newBoard() {
42	    const name = prompt("New board name (e.g. Soul Pilates)");
43	    if (!name?.trim()) return;
44	    const res = await createBoard(name.trim());
45	    if (res.id) router.push(`/admin/board?b=${res.id}`);
46	  }
47	
48	  async function onDrop(colId: string, index: number) {
49	    if (!drag) return;
50	    const cardId = drag;
51	    setDrag(null);
52	    // Optimistic: remove from old col, insert into new.
53	    setCols((prev) => {
54	      let moved: CardSummary | undefined;
55	      const stripped = prev.map((c) => ({ ...c, cards: c.cards.filter((cd) => (cd.id === cardId ? ((moved = cd), false) : true)) }));
56	      if (!moved) return prev;
57	      return stripped.map((c) => (c.id === colId ? { ...c, cards: [...c.cards.slice(0, index), moved!, ...c.cards.slice(index)] } : c));
58	    });
59	    await moveCard(cardId, colId, index);
60	  }
61	
62	  return (
63	    // Fill the viewport so the board occupies the page instead of floating in a
64	    // sea of dead space. Height is viewport-relative (works regardless of the
65	    // admin shell's own layout); the columns row below takes the remaining space.
66	    <div className="flex h-[calc(100vh-6.5rem)] flex-col gap-3">
67	      {/* Board switcher */}
68	      <div className="flex flex-shrink-0 flex-wrap items-center gap-2">
69	        <h1 className="mr-2 text-lg font-semibold">Boards</h1>
70	        {boards.map((b) => (
71	          <a
72	            key={b.id}
73	            href={`/admin/board?b=${b.id}`}
74	            className={`rounded-lg px-3 py-1.5 text-sm ${b.id === board?.id ? "bg-brand-500/20 text-brand-100" : "text-slate-400 hover:bg-white/5"}`}
75	          >
76	            {b.name} <span className="text-xs text-slate-500">{b.cardCount}</span>
77	          </a>
78	        ))}
79	        <button onClick={newBoard} className="rounded-lg border border-white/10 px-3 py-1.5 text-sm text-slate-300 hover:bg-white/5">+ Board</button>
80	      </div>
81	
82	      {!board ? (
83	        <p className="text-sm text-slate-400">No board yet.</p>
84	      ) : (
85	        <div className="flex min-h-0 flex-1 items-stretch gap-4 overflow-x-auto pb-2">
86	          {cols.map((col) => (
87	            <Column key={col.id} col={col} onOpen={setOpenCard} onDragCard={setDrag} onDrop={onDrop} dragging={drag} />
88	          ))}
89	          <NewColumn boardId={board.id} onDone={() => router.refresh()} />
90	        </div>
91	      )}
92	
93	      {openCard && <CardModal cardId={openCard} onClose={() => { setOpenCard(null); router.refresh(); }} />}
94	    </div>
95	  );
96	}
97	
98	function Column({
99	  col, onOpen, onDragCard, onDrop, dragging,
100	}: { col: ColumnData; onOpen: (id: string) => void; onDragCard: (id: string) => void; onDrop: (colId: string, index: number) => void; dragging: string | null }) {
101	  const [adding, setAdding] = useState(false);
102	  const [title, setTitle] = useState("");
103	  const router = useRouter();
104	  async function add() {
105	    if (!title.trim()) return;
106	    await createCard(col.id, title.trim());
107	    setTitle(""); setAdding(false); router.refresh();
108	  }
109	  return (
110	    <div
111	      className="flex h-full w-72 shrink-0 flex-col rounded-xl border border-white/[0.06] bg-white/[0.02]"
112	      onDragOver={(e) => { if (dragging) e.preventDefault(); }}
113	      onDrop={() => onDrop(col.id, col.cards.length)}
114	    >
115	      <div className="flex flex-shrink-0 items-center justify-between px-3 py-2">
116	        <span className="text-sm font-medium text-slate-300">{col.name}</span>
117	        <span className="text-xs text-slate-500">{col.cards.length}</span>
118	      </div>
119	      <div className="flex-1 space-y-2 overflow-y-auto px-2 pb-2">
120	        {col.cards.map((card, i) => (
121	          <div
122	            key={card.id}
123	            draggable
124	            onDragStart={() => onDragCard(card.id)}
125	            onDrop={(e) => { e.stopPropagation(); onDrop(col.id, i); }}
126	            onDragOver={(e) => { if (dragging) e.preventDefault(); }}
127	            onClick={() => onOpen(card.id)}
128	            className="cursor-pointer rounded-lg border border-white/[0.06] bg-navy-850/80 p-2.5 hover:border-white/15"
129	          >
130	            <div className="mb-1 flex items-center gap-1.5">
131	              <span className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${TYPE_TONE[card.type]}`}>{card.type.toLowerCase()}</span>
132	              <span className={`h-2 w-2 rounded-full ${PRIORITY_DOT[card.priority]}`} title={card.priority} />
133	            </div>
134	            <p className="text-sm text-slate-200">{card.title}</p>
135	            <div className="mt-1.5 flex items-center gap-2 text-[11px] text-slate-500">
136	              {card.assignee && <span>@{card.assignee}</span>}
137	              {card.attachmentCount > 0 && <span>📎 {card.attachmentCount}</span>}
138	              {card.commentCount > 0 && <span>💬 {card.commentCount}</span>}
139	              {card.hasDescription && <span>≡</span>}
140	            </div>
141	          </div>
142	        ))}
143	      </div>
144	      {adding ? (
145	        <div className="p-2">
146	          <textarea autoFocus className="input text-sm" rows={2} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Card title…" onKeyDown={(e) => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); add(); } }} />
147	          <div className="mt-1 flex gap-2"><button className="btn-primary text-xs" onClick={add}>Add</button><button className="btn-secondary text-xs" onClick={() => setAdding(false)}>Cancel</button></div>
148	        </div>
149	      ) : (
150	        <button className="px-3 py-2 text-left text-xs text-slate-500 hover:text-slate-300" onClick={() => setAdding(true)}>+ Add card</button>
151	      )}
152	    </div>
153	  );
154	}
155	
156	function NewColumn({ boardId, onDone }: { boardId: string; onDone: () => void }) {
157	  const [name, setName] = useState("");
158	  return (
159	    <div className="w-64 shrink-0">
160	      <div className="flex items-center gap-2 rounded-xl border border-dashed border-white/10 p-2">
161	        <input className="input text-sm" placeholder="+ New stage" value={name} onChange={(e) => setName(e.target.value)} onKeyDown={async (e) => { if (e.key === "Enter" && name.trim()) { await createColumn(boardId, name.trim()); setName(""); onDone(); } }} />
162	      </div>
163	    </div>
164	  );
165	}
166	
167	function CardModal({ cardId, onClose }: { cardId: string; onClose: () => void }) {
168	  const [card, setCard] = useState<CardDetail | null>(null);
169	  const [desc, setDesc] = useState("");
170	  const [comment, setComment] = useState("");
171	  const [uploading, setUploading] = useState(false);
172	  const fileRef = useRef<HTMLInputElement>(null);
173	
174	  async function load() { const c = await getCard(cardId); setCard(c); if (c) setDesc(c.description); }
175	  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [cardId]);
176	
177	  if (!card) return null;
178	
179	  async function patch(p: Parameters<typeof updateCard>[1]) { await updateCard(cardId, p); load(); }
180	
181	  async function uploadFiles(files: File[]) {
182	    if (!files.length) return;
183	    setUploading(true);
184	    for (const f of files) {
185	      const fd = new FormData();
186	      fd.append("file", f);
187	      try {
188	        const res = await fetch(`/api/board/attachments?cardId=${cardId}`, { method: "POST", body: fd });
189	        if (!res.ok) {
190	          const body = await res.json().catch(() => ({}));
191	          // Don't swallow failures silently — that made an upload look like it did
192	          // nothing. Tell the operator what went wrong.
193	          alert(`Upload failed for “${f.name}”: ${body.error ?? `HTTP ${res.status}`}`);
194	        }
195	      } catch {
196	        alert(`Upload failed for “${f.name}” — network error.`);
197	      }
198	    }
199	    setUploading(false);
200	    if (fileRef.current) fileRef.current.value = "";
201	    load();
202	  }
203	
204	  // Paste a screenshot (or any image) from the clipboard anywhere in the card —
205	  // grab image items, name them uniquely (the clipboard rarely supplies a name),
206	  // and upload them as attachments. Non-image pastes fall through untouched, so
207	  // pasting text into the description/comment still works normally.
208	  async function onPaste(e: ClipboardEvent<HTMLDivElement>) {
209	    const imgs: File[] = [];
210	    for (const item of Array.from(e.clipboardData.items)) {
211	      if (item.type.startsWith("image/")) {
212	        const f = item.getAsFile();
213	        if (f) {
214	          const ext = (item.type.split("/")[1] || "png").split("+")[0];
215	          imgs.push(new File([f], `pasted-${Date.now()}.${ext}`, { type: item.type }));
216	        }
217	      }
218	    }
219	    if (imgs.length) {
220	      e.preventDefault();
221	      await uploadFiles(imgs);
222	    }
223	  }
224	
225	  return (
226	    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/60 p-4" onClick={onClose}>
227	      <div className="mt-8 w-full max-w-2xl rounded-2xl border border-white/10 bg-navy-900 p-5" onClick={(e) => e.stopPropagation()} onPaste={onPaste}>
228	        <div className="flex items-start justify-between gap-3">
229	          <input className="input flex-1 text-lg font-semibold" defaultValue={card.title} onBlur={(e) => e.target.value !== card.title && patch({ title: e.target.value })} />
230	          <button className="text-slate-400 hover:text-white" onClick={onClose}>✕</button>
