function slugify(name: string): string {
  return name.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "app";
}

/** All apps/products, oldest first, with their board counts. */
export async function listApps(): Promise<AppSummary[]> {
  await requireAdmin();
  const apps = await db.app.findMany({ orderBy: { createdAt: "asc" }, include: { _count: { select: { boards: true } } } });
  return apps.map((a) => ({ id: a.id, name: a.name, slug: a.slug, color: a.color, boardCount: a._count.boards }));
}

export async function createApp(name: string, color?: string | null): Promise<{ id?: string; error?: string }> {
  await requireAdmin();
  const clean = String(name ?? "").trim().slice(0, 60);
  if (!clean) return { error: "Enter an app name." };
  // Ensure a unique slug even when two apps share a base name.
  let slug = slugify(clean);
  for (let n = 2; await db.app.findUnique({ where: { slug } }); n++) slug = `${slugify(clean)}-${n}`;
  const app = await db.app.create({ data: { name: clean, slug, color: color?.trim() || null } });
  revalidatePath("/admin/board");
  return { id: app.id };
}

