/** Reorder a column within its board; renumber siblings. */
export async function moveColumn(columnId: string, toIndex: number): Promise<void> {
  await requireAdmin();
  const col = await db.boardColumn.findUnique({ where: { id: columnId }, select: { boardId: true } });
  if (!col) return;
  const siblings = await db.boardColumn.findMany({
    where: { boardId: col.boardId, NOT: { id: columnId } },
    orderBy: { position: "asc" },
    select: { id: true },
  });
  const order = siblings.map((s) => s.id);
  const idx = Math.max(0, Math.min(toIndex, order.length));
  order.splice(idx, 0, columnId);
  await db.$transaction(order.map((id, i) => db.boardColumn.update({ where: { id }, data: { position: i } })));
  revalidatePath("/admin/board");
}

// ---- Search ----------------------------------------------------------------

/** Full-text-ish search over card title, description and comment bodies
 *  (Postgres case-insensitive contains). Scoped to a board, or to an app (all
 *  its boards). Skips archived cards. */
export async function searchCards(
  scope: { boardId?: string | null; appId?: string | null },
  query: string,
): Promise<CardSearchHit[]> {
  await requireAdmin();
  const q = String(query ?? "").trim();
  if (q.length < 2) return [];
  const boardWhere =
    scope.boardId ? { boardId: scope.boardId } : scope.appId ? { board: { appId: scope.appId } } : {};
  const cards = await db.card.findMany({
    where: {
      archivedAt: null,
      ...boardWhere,
      OR: [
        { title: { contains: q, mode: "insensitive" } },
        { description: { contains: q, mode: "insensitive" } },
        { comments: { some: { body: { contains: q, mode: "insensitive" } } } },
      ],
    },
    include: {
      board: { select: { name: true } },
      column: { select: { name: true } },
      comments: { where: { body: { contains: q, mode: "insensitive" } }, take: 1, orderBy: { createdAt: "desc" } },
    },
    orderBy: { updatedAt: "desc" },
    take: 50,
  });
  const lower = q.toLowerCase();
  const snippetAround = (text: string): string => {
    const i = text.toLowerCase().indexOf(lower);
    if (i < 0) return text.slice(0, 120);
    const start = Math.max(0, i - 40);
    return (start > 0 ? "…" : "") + text.slice(start, i + q.length + 60).trim() + (i + q.length + 60 < text.length ? "…" : "");
  };
  return cards.map((c) => {
    let matchedIn: CardSearchHit["matchedIn"] = "title";
    let snippet = c.title;
    if (!c.title.toLowerCase().includes(lower)) {
      if (c.description.toLowerCase().includes(lower)) {
        matchedIn = "description";
        snippet = snippetAround(c.description);
      } else if (c.comments[0]) {
        matchedIn = "comment";
        snippet = snippetAround(c.comments[0].body);
      }
    }
    return {
      id: c.id,
      boardId: c.boardId,
      boardName: c.board.name,
      columnId: c.columnId,
      columnName: c.column.name,
      title: c.title,
      type: c.type,
      priority: c.priority,
      snippet,
      matchedIn,
    };
  });
}

