// Deterministic chip colour for a label so the same label always looks the same.
const LABEL_PALETTE = [
  "bg-rose-500/15 text-rose-300", "bg-amber-500/15 text-amber-300", "bg-emerald-500/15 text-emerald-300",
  "bg-sky-500/15 text-sky-300", "bg-violet-500/15 text-violet-300", "bg-teal-500/15 text-teal-300",
  "bg-fuchsia-500/15 text-fuchsia-300", "bg-lime-500/15 text-lime-300",
];
function labelColor(label: string): string {
  let h = 0;
  for (let i = 0; i < label.length; i++) h = (h * 31 + label.charCodeAt(i)) >>> 0;
  return LABEL_PALETTE[h % LABEL_PALETTE.length];
}
function relativeTime(iso: string): string {
  const then = new Date(iso).getTime();
  const s = Math.max(0, Math.floor((Date.now() - then) / 1000));
  if (s < 60) return "just now";
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  const d = Math.floor(h / 24);
  if (d < 30) return `${d}d ago`;
  return new Date(iso).toLocaleDateString();
}
/** Split text around the first case-insensitive match of `q`, wrapping the match. */
function highlight(text: string, q: string) {
  if (!q) return text;
  const i = text.toLowerCase().indexOf(q.toLowerCase());
  if (i < 0) return text;
  return (
    <>
      {text.slice(0, i)}
      <mark className="rounded bg-amber-400/30 text-amber-100">{text.slice(i, i + q.length)}</mark>
      {text.slice(i + q.length)}
    </>
  );
}

