function Column({
  col, index, cards, totalCount, onOpen, drag, setDrag, onDropCard, onDropColumn, dragEnabled, searchQ, adding, onStartAdd, onCancelAdd, onRefresh,
}: {
  col: ColumnData;
  index: number;
  cards: CardSummary[];
  totalCount: number;
  onOpen: (id: string) => void;
  drag: DragState;
  setDrag: (d: DragState) => void;
  onDropCard: (colId: string, index: number) => void;
  onDropColumn: (targetIndex: number) => void;
  dragEnabled: boolean;
  searchQ: string;
  adding: boolean;
  onStartAdd: () => void;
  onCancelAdd: () => void;
  onRefresh: () => void;
}) {
  const [title, setTitle] = useState("");
  const [editingName, setEditingName] = useState(false);
  const [name, setName] = useState(col.name);
  const [dropIdx, setDropIdx] = useState<number | null>(null); // card insert indicator
  const [colOver, setColOver] = useState(false); // column reorder indicator
  useEffect(() => setName(col.name), [col.name]);

  const draggingCard = drag?.kind === "card";
  const draggingColumn = drag?.kind === "column";

  async function add() {
    if (!title.trim()) return;
    await createCard(col.id, title.trim());
    setTitle(""); onCancelAdd(); onRefresh();
  }
  async function saveName() {
    setEditingName(false);
    if (name.trim() && name.trim() !== col.name) { await renameColumn(col.id, name.trim()); onRefresh(); }
    else setName(col.name);
  }
  async function removeColumn() {
    if (totalCount > 0) { alert("Move or archive its cards first."); return; }
    if (!confirm(`Delete the empty “${col.name}” stage?`)) return;
    const res = await deleteColumn(col.id);
    if (res.error) alert(res.error); else onRefresh();
  }

  return (
    <div
      className={`flex h-full w-64 shrink-0 flex-col rounded-xl border bg-white/[0.02] ${
        draggingColumn && colOver ? "border-brand-400" : "border-white/[0.06]"
      }`}
      // Column-reorder drop target: accept a dragged column header.
      onDragOver={(e) => { if (draggingColumn) { e.preventDefault(); setColOver(true); } }}
      onDragLeave={() => setColOver(false)}
      onDrop={(e) => {
        if (draggingColumn) { e.preventDefault(); setColOver(false); onDropColumn(index); }
        else if (draggingCard) { setDropIdx(null); onDropCard(col.id, totalCount); }
      }}
    >
      <div
        className="flex flex-shrink-0 items-center justify-between gap-1 px-3 py-2"
        draggable={!editingName}
        onDragStart={(e) => { if (!editingName) { e.stopPropagation(); setDrag({ kind: "column", id: col.id }); } }}
        title="Drag to reorder · double-click to rename"
      >
        {editingName ? (
          <input
            autoFocus
            className="input py-0.5 text-sm"
            value={name}
            onChange={(e) => setName(e.target.value)}
            onBlur={saveName}
            onKeyDown={(e) => { if (e.key === "Enter") saveName(); if (e.key === "Escape") { setName(col.name); setEditingName(false); } }}
          />
        ) : (
          <span className="cursor-grab select-none text-sm font-medium text-slate-300" onDoubleClick={() => setEditingName(true)}>
            {col.name}
          </span>
        )}
        <span className="flex items-center gap-1.5">
          <span className="text-xs text-slate-500">{cards.length !== totalCount ? `${cards.length}/${totalCount}` : totalCount}</span>
          {totalCount === 0 && !editingName && (
            <button onClick={removeColumn} className="text-xs text-slate-600 hover:text-red-400" title="Delete empty stage">✕</button>
          )}
        </span>
      </div>
      <div
        className="flex-1 space-y-2 overflow-y-auto px-2 pb-2"
        onDragOver={(e) => { if (draggingCard) { e.preventDefault(); if (dropIdx === null) setDropIdx(cards.length); } }}
      >
        {cards.map((card, i) => (
          <div key={card.id}>
            {draggingCard && dropIdx === i && <div className="mb-2 h-0.5 rounded bg-brand-400" />}
            <div
              draggable={dragEnabled}
              onDragStart={(e) => { if (dragEnabled) { e.stopPropagation(); setDrag({ kind: "card", id: card.id }); } }}
              onDragOver={(e) => { if (draggingCard) { e.preventDefault(); e.stopPropagation(); setDropIdx(i); } }}
              onDrop={(e) => { if (draggingCard) { e.stopPropagation(); setDropIdx(null); onDropCard(col.id, i); } }}
              onClick={() => onOpen(card.id)}
              className={`cursor-pointer rounded-lg border border-white/[0.06] bg-navy-850/80 p-2.5 hover:border-white/15 ${drag?.kind === "card" && drag.id === card.id ? "opacity-40" : ""}`}
            >
