async function runStage(action: StageAction) {
  const label = STAGE_ACTION_LABELS[action];
  // Production and GitHub are irreversible/public — spell that out in the confirm.
  const extra =
    action === "production" ? "\n\nThis promotes the current staging build to PRODUCTION."
    : action === "github" ? "\n\nThis commits ALL current changes and auto-pushes to GitHub."
    : "";
  if (!confirm(`Run “${label}” for this card?${extra}\n\nOutput is captured and posted back as a comment.`)) return;
  setRunning(action);
  try {
    const res = await runCardStageAction(cardId, action);
    if (res.error) alert(`Could not start: ${res.error}`);
  } finally {
    setRunning(null);
    load();
  }
}

if (!card) return null;

